using ClinicaEsteticaWeb.Models;using ClinicaEsteticaWeb.Services;using MySqlConnector;using Microsoft.AspNetCore.Mvc;
namespace ClinicaEsteticaWeb.Controllers;
public class ProcedimentosController:Controller {private readonly Db _db;public ProcedimentosController(Db db)=>_db=db;public IActionResult Index(){var l=new List<Procedimento>();using var x=_db.Open();using var c=new MySqlCommand("SELECT * FROM procedimento ORDER BY nome",x);using var r=c.ExecuteReader();while(r.Read())l.Add(new Procedimento{Id=r.GetInt32("id"),Nome=r.GetString("nome"),Descricao=r.IsDBNull(r.GetOrdinal("descricao"))?"":r.GetString("descricao"),DuracaoMinutos=r.GetInt32("duracao_minutos"),Valor=r.GetDecimal("valor"),Status=r.GetString("status")});return View(l);}[HttpGet]public IActionResult Create()=>View(new Procedimento{Status="ativo"});[HttpPost][ValidateAntiForgeryToken]public IActionResult Create(Procedimento p){using var x=_db.Open();using var c=new MySqlCommand("INSERT INTO procedimento(nome,descricao,duracao_minutos,valor,status) VALUES(@n,@d,@du,@v,@s)",x);c.Parameters.AddWithValue("@n",p.Nome);c.Parameters.AddWithValue("@d",p.Descricao??"");c.Parameters.AddWithValue("@du",p.DuracaoMinutos);c.Parameters.AddWithValue("@v",p.Valor);c.Parameters.AddWithValue("@s",p.Status??"ativo");c.ExecuteNonQuery();return RedirectToAction(nameof(Index));}[HttpPost][ValidateAntiForgeryToken]public IActionResult Delete(int id){using var x=_db.Open();using var c=new MySqlCommand("DELETE FROM procedimento WHERE id=@id",x);c.Parameters.AddWithValue("@id",id);c.ExecuteNonQuery();return RedirectToAction(nameof(Index));}}
